      y: 10,
      // More movement
      staggerRange: [0.08, 0.25] // Wider stagger range
    });
    if (elementTimeline) {
      masterTimeline.add(elementTimeline, index * getRandomValue(0.05, 0.2));
    }
  });

  // Paragraphs with a slight delay
  paragraphs.forEach((element, index) => {
    const elementTimeline = animateText(element, {
      ...options,
      delay: getChaoticValue(0.1, 0.5) * index,
      blur: 6,
      staggerRange: [0.02, 0.1]
    });
    if (elementTimeline) {
      masterTimeline.add(elementTimeline, 0.5 + index * getRandomValue(0.1, 0.4));
    }
  });

