      display: inline-block;
      width: auto;
    }
  `;
  document.head.appendChild(styleEl);
};

// Initialize styles on load
if (typeof document !== 'undefined') {
  addAnimationStyles();
}

/**
 * Main function to animate all content
 */
export const animateAllContent = () => {
  // Add styles
  if (typeof document !== 'undefined') {
    addAnimationStyles();
  }

  // Kill any running animations to prevent conflicts
  gsap.killTweensOf('.gsap-char');

  // Animate main content
  const mainContent = document.querySelector('.main-content');
  if (mainContent) {
    // First fade in the container as a whole (slower and more organic)
    gsap.fromTo(mainContent, {
      opacity: 0.5
    }, {
      opacity: 1,
      duration: 0.8,
      ease: "power2.inOut"
    });

    // Then animate text within with more chaotic timing
    setTimeout(() => {
      animateTextInContainer(mainContent, {
        staggerRange: [0.05, 0.2],
        excludeSelectors: ['.alien-title', '.no-animate', 'button', 'input']
      });
    }, getRandomValue(200, 500)); // Add random delay before starting text animation
  }

  // Add more random timing to container fade-ins
  const categoryContainers = document.querySelectorAll('.categories, .subcategories, .category-links');
  if (categoryContainers.length) {
    gsap.fromTo(categoryContainers, {
      opacity: 0,
      y: () => getRandomValue(5, 15)
    }, {
      opacity: 1,
      y: 0,
      duration: () => getRandomValue(0.6, 1.2),
      ease: "power1.inOut",
      stagger: {
        amount: getRandomValue(0.3, 0.8),
        from: "random"
      }
    });
  }

  // Handle category items with organic, chaotic animations
  const categoryItems = document.querySelectorAll('.category-item');
  if (categoryItems.length) {
    // Fade in the items with varied timing
    gsap.fromTo(categoryItems, {
      opacity: 0,
      y: i => getRandomValue(5, 20),
      x: i => getRandomValue(-5, 5),
      scale: 0.95
    }, {
      opacity: 1,
      y: 0,
      x: 0,
      scale: 1,
      duration: i => getRandomValue(0.5, 0.9),
      stagger: {
        each: 0.08,
        from: "random",
        ease: "power1.inOut"
      },
      ease: "back.out(1.2)",
      onComplete: () => {
        // After items fade in, animate their text with chaotic timing
        categoryItems.forEach((item, index) => {
          setTimeout(() => {
            const link = item.querySelector('a');
            if (link) {
              animateText(link, {
                staggerRange: [0.01, 0.08],
                blur: getRandomValue(2, 5),
                duration: getRandomValue(0.4, 0.8)
              });
            }
            const count = item.querySelector('.count');
            if (count) {
              setTimeout(() => {
                animateText(count, {
                  staggerRange: [0.005, 0.03],
                  blur: getRandomValue(1, 3),
                  duration: getRandomValue(0.3, 0.6)
                });
              }, getRandomValue(50, 300)); // Random delay for count animation
            }
          }, index * getRandomValue(30, 150)); // Random delay based on index
        });
      }
    });
  }
};

// Create a named export object
const textAnimator = {
  animateText,
  animateTextInContainer,
  animateAllContent
